ret = bg*vec3(0.3,0.5,0.7);
ret = mix(ret,vec3(0.2,0.1, 0.0),GetPixel(uv + vec2(dx.x,dy.x)*(vec2(1.0)/uTexSize) * 18.0).x * 6.0);
