dx = ( 2.0 * GetBlur1(uv+vec2( 1.0 , 0.0 )*d) - 2.0*GetBlur1(uv-vec2( 1.0 , 0.0 )*d).xy )*0.5;
dy = ( 2.0 * GetBlur1(uv+vec2( 0.0 , 1.0 )*d) - 2.0*GetBlur1(uv-vec2( 0.0 , 1.0 )*d).xy )*0.5;
dz +=vec2(dx.y,dy.y);
vec3 bg = pow(length(dz)*0.8+0,0.7) + GetBlur2(uv).y*0.4-0.1;
ret = bg*vec3(0.3,0.5,0.7);
